UPDATE book SET series_id = NULL;
DELETE FROM series_has_theme;
DELETE FROM user_follows_series;
DELETE FROM series;

INSERT INTO user_sells_book (user_id, book_id, status, created_at, updated_at)
SELECT user_id, book_id, UPPER(status), created_at, updated_at
FROM user_owns_book
WHERE UPPER(status) IN ('FOR_SALE', 'SOLD')
ON CONFLICT (user_id, book_id) DO NOTHING;

DELETE FROM user_owns_book WHERE UPPER(status) IN ('FOR_SALE', 'SOLD');
